class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        x = reduce(lambda a, b: a ^ b, nums)
        diff = x & -x
        a = 0
        for v in nums:
            if v & diff:
                a ^= v
        return sorted([a, x ^ a])

