func minFlips(a int, b int, c int) int {
	flips := 0
	for a > 0 || b > 0 || c > 0 {
		x, y, z := a&1, b&1, c&1
		if z == 1 {
			flips += (x | y) ^ 1 // need at least one 1
		} else {
			flips += x + y // both must be 0
		}
		a, b, c = a>>1, b>>1, c>>1
	}
	return flips
}

