class Solution:
    def minEnd(self, n: int, x: int) -> int:
        res, k, bit = x, n - 1, 1
        while k:
            if not x & bit:              # free position: place the next bit of n - 1
                if k & 1:
                    res |= bit
                k >>= 1
            bit <<= 1
        return res

